from pathlib import Path
p=Path(__file__).parent
p.joinpath('folded-link').mkdir(exist_ok=True)
d=p/'folded-link'
a='M138 43H91C60 43 42 61 42 92V133C42 164 60 182 91 182H108L133 157H93C76 157 67 148 67 131V94C67 77 76 68 93 68H128L153 93 171 75Z'
b='M118 213H165C196 213 214 195 214 164V123C214 92 196 74 165 74H148L123 99H163C180 99 189 108 189 125V162C189 179 180 188 163 188H128L103 163 85 181Z'
# The two ribbons share the same weight, radius and cut angle; no secondary badge.
geometry=f'<path d="{a}"/><path d="{b}"/>'
defs='''<defs><linearGradient id="bg" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#303846"/><stop offset=".55" stop-color="#1e2633"/><stop offset="1" stop-color="#131b28"/></linearGradient><linearGradient id="a" x1=".1" y1="1" x2=".85" y2="0"><stop stop-color="#a5f3da"/><stop offset=".5" stop-color="#83e1ed"/><stop offset="1" stop-color="#8cbcff"/></linearGradient><linearGradient id="b" x1=".1" y1="1" x2=".85" y2="0"><stop stop-color="#75c2f4"/><stop offset=".5" stop-color="#9cb1fc"/><stop offset="1" stop-color="#c2afff"/></linearGradient><linearGradient id="edge" x2=".7" y2="1"><stop stop-color="#fff" stop-opacity=".8"/><stop offset=".45" stop-color="#fff" stop-opacity=".15"/><stop offset="1" stop-color="#fff" stop-opacity="0"/></linearGradient><filter id="shadow" x="-30%" y="-30%" width="160%" height="170%"><feDropShadow dx="0" dy="4" stdDeviation="4" flood-color="#000b22" flood-opacity=".28"/></filter></defs>'''
color=f'<g id="ribbons"><path d="{a}" fill="url(#a)"/><path d="{b}" fill="url(#b)"/></g>'
edge='''<g id="highlights" fill="none" stroke="url(#edge)" stroke-width="1.2" stroke-linecap="round"><path d="M43 132V92C43 62 61 44 91 44H137L169 75"/><path d="M149 75H165C195 75 213 93 213 123V163"/><path d="M68 130C68 147 77 156 93 156H130"/><path d="M129 187H163C179 187 188 178 188 162"/></g>'''
def wrap(content,view='0 0 256 256',defs_=defs):
 return f'<svg xmlns="http://www.w3.org/2000/svg" width="1024" height="1024" viewBox="{view}">{defs_}{content}</svg>'
app=wrap('<g id="background"><rect width="256" height="256" fill="url(#bg)"/></g><g id="mark" filter="url(#shadow)">'+color+edge+'</g>')
(d/'app-ios.svg').write_text(app)
(d/'brand-dark.svg').write_text(wrap(color))
(d/'brand-light.svg').write_text(wrap('<g fill="#304b70">'+geometry+'</g>',defs_=''))
(d/'menubar-template.svg').write_text(wrap('<g fill="#000">'+geometry+'</g>',view='30 30 196 196',defs_=''))
(d/'favicon.svg').write_text(wrap('<g fill="#000">'+geometry+'</g>',view='30 30 196 196',defs_=''))
